def closestPairSum(a, b, target):
    i, j = 0, len(b) - 1
    best = None
    while i < len(a) and j >= 0:
        s = a[i] + b[j]
        d = abs(s - target)
        if best is None or d < best:
            best = d
        if s < target:
            i += 1
        elif s > target:
            j -= 1
        else:
            return 0
    return best
